window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c1cf32a17b39147e"]={"versions": [{"id": "FIG-c1cf32a17b39147e", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-2.0-Metamodell-Klassendiagramm (M2-Ebene nach AUTOSAR-Metamodell-Architektur).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP), Teilspezifikation <em>Manifest Specification</em> (<code>AUTOSAR_TPS_ManifestSpecification</code>, Release R19-11).\n</li><li><strong>Funktionaler Zweck:</strong> Modellierung der Zugriffsberechtigungen für Kommunikations-Events im Rahmen des <em>Identity and Access Management</em> (IAM) und des <em>Communication Management</em> (<code>ara::com</code>). Es definiert die formalen Beziehungen zur Gewährung von Zugriffsrechten (<code>ComEventGrant</code>) auf Instanz- und Deployment-Ebene sowie deren Entsprechung im Software-Design (<code>ComEventGrantDesign</code>) gemäß den Anforderungen <code>RS_MANI_00060</code> und <code>TPS_MANI_01240</code>.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen &amp; Stereotypen</h5>\n<ul class=\"fig-list\"><li><strong><code>ComEventGrant</code></strong> (Spezialisierung von <code>Grant</code>):\n<ul class=\"fig-list\"><li>Zentrales Deployment-Artefakt zur Freigabe des Zugriffs auf ein bestimmtes Event einer Service-Instanz.\n</li><li>Generalisiert von <code>ARElement</code> via <code>Grant</code>.\n</li><li>Assoziationen:\n<ul class=\"fig-list\"><li><code>+serviceInstance</code>: Referenziert genau eine (<code>[1]</code>) Instanz von <code>AdaptivePlatformServiceInstance</code>.\n</li><li><code>+serviceDeployment</code>: Referenziert genau ein (<code>[1]</code>) Event-Deployment <code>ServiceEventDeployment</code>.\n</li><li><code>+design</code> (<code>«atpUriDef»</code>): Optionale Referenz (<code>[0..1]</code>) auf das korrespondierende Entwurfsartefakt <code>ComEventGrantDesign</code>.\n</li></ul>\n</li></ul>\n</li><li><strong><code>ComEventGrantDesign</code></strong> (Spezialisierung von <code>GrantDesign</code>):\n<ul class=\"fig-list\"><li>Entwurfszeit-Pendant zur Spezifikation von Berechtigungen auf Software-Architekturebene unabhängig vom konkreten Deployment.\n</li></ul>\n</li><li><strong><code>GrantDesign</code></strong> (<code>ARElement</code>):\n<ul class=\"fig-list\"><li>Abstrakte Basisklasse für Design-Grants.\n</li><li>Assoziation: Referenziert über <code>+processDesign</code> optional (<code>[0..1]</code>) ein <code>ProcessDesign</code>.\n</li></ul>\n</li><li><strong><code>ProcessDesign</code></strong> (<code>ARElement</code>):\n<ul class=\"fig-list\"><li>Repräsentiert den Prozessentwurf auf Architekturebene.\n</li><li>Wird referenziert von:\n<ul class=\"fig-list\"><li><code>Process</code> über Rolle <code>+design [0..1]</code>.\n</li><li><code>ServiceInstanceToPortPrototypeMapping</code> über Rolle <code>+process [0..1]</code>.\n</li></ul>\n</li></ul>\n</li><li><strong><code>Process</code></strong> (Spezialisierung von <code>AbstractExecutionContext</code>):\n<ul class=\"fig-list\"><li>Repräsentiert die konkrete OS-Prozessinstanz zur Laufzeit.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>logTraceDefaultLogLevel: LogTraceDefaultLogLevelEnum [0..1]</code>\n</li><li><code>logTraceFilePath: UriString [0..1]</code>\n</li><li><code>logTraceLogMode: LogTraceLogModeEnum [0..*]</code>\n</li><li><code>logTraceProcessDesc: String [0..1]</code>\n</li><li><code>logTraceProcessId: String [0..1]</code>\n</li><li><code>numberOfRestartAttempts: PositiveInteger [0..1]</code>\n</li><li><code>preMapping: Boolean [0..1]</code>\n</li></ul>\n</li></ul>\n</li><li><strong><code>AdaptivePlatformServiceInstance</code></strong> (<code>UploadablePackageElement</code>):\n<ul class=\"fig-list\"><li>Repräsentiert eine konkrete (bereitgestellte oder konsumierte) Service-Instanz auf der Adaptive Platform.\n</li><li>Assoziation: Referenziert über <code>+serviceInterfaceDeployment</code> optional (<code>[0..1]</code>) ein <code>ServiceInterfaceDeployment</code>.\n</li></ul>\n</li><li><strong><code>ServiceInterfaceDeployment</code></strong> (<code>UploadablePackageElement</code>):\n<ul class=\"fig-list\"><li>Protokollspezifische Bindung eines Service-Interfaces (z. B. SOME/IP).\n</li><li>Komposition (schwarze Raute): Aggregiert <code>0..*</code> <code>ServiceEventDeployment</code>-Elemente über die Rolle <code>+eventDeployment</code>.\n</li></ul>\n</li><li><strong><code>ServiceEventDeployment</code></strong> (<code>Identifiable</code>):\n<ul class=\"fig-list\"><li>Transport- und serialisierungsspezifisches Deployment eines einzelnen Events (z. B. SOME/IP Event ID, Event Groups).\n</li></ul>\n</li><li><strong><code>ServiceInstanceToPortPrototypeMapping</code></strong> (<code>UploadablePackageElement</code>):\n<ul class=\"fig-list\"><li>Verknüpft Ports mit Service-Instanzen und Prozessen.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>enablesLogTrace: Boolean [0..1]</code>\n</li><li><code>logTracePortId: String [0..1]</code>\n</li></ul>\n</li><li>Assoziationen:\n<ul class=\"fig-list\"><li><code>+serviceInstance</code>: Referenziert <code>[0..1]</code> <code>AdaptivePlatformServiceInstance</code>.\n</li><li><code>+portPrototype</code> (<code>«instanceRef,atpUriDef»</code>): Instanzreferenz (<code>[0..1]</code>) auf ein <code>PortPrototype</code>.\n</li></ul>\n</li></ul>\n</li><li><strong><code>PortPrototype</code></strong> (<code>AtpBlueprintable</code>, <code>AtpPrototype</code>):\n<ul class=\"fig-list\"><li>Architektureller Kommunikationsendpunkt (RPort/PPort) einer Software-Komponente.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell für den Manifest-Entwurf handelt, existiert kein Sequenzdiagramm; das Diagramm determiniert jedoch zwingend folgende Laufzeitabläufe im AP IAM- und IPC-Stack:</p>\n<ol class=\"fig-list\"><li><strong>Deployment- &amp; Startphase (Execution Management):</strong>\n<ul class=\"fig-list\"><li>Beim Parsen des <em>Execution Manifests</em> und des <em>Service Instance Manifests</em> erzeugt die IAM-Instanz Zugriffskontrolltabellen (ACLs / Capabilities) für den jeweiligen <code>Process</code>.\n</li></ul>\n</li><li><strong>Access Control Check (<code>ara::com</code> Subscription/FindService):</strong>\n<ul class=\"fig-list\"><li>Ruft eine Applikation innerhalb eines Prozesses Methoden wie <code>FindService()</code>, <code>Subscribe()</code> oder <code>Send()</code> für ein Event auf, fängt der Middleware-Stack (<code>ara::com</code>) bzw. der IAM-Policy-Enforcement-Point (PEP) die Anfrage ab.\n</li></ul>\n</li><li><strong>Validierungspfad:</strong>\n<ul class=\"fig-list\"><li>Der PEP prüft, ob die Prozess-ID/UID über das Mapping (<code>ServiceInstanceToPortPrototypeMapping</code> → <code>AdaptivePlatformServiceInstance</code>) eine explizite <code>ComEventGrant</code>-Freigabe für das konkrete <code>ServiceEventDeployment</code> besitzt.\n</li></ul>\n</li><li><strong>Fehlerpfad &amp; Abbruchbedingung:</strong>\n<ul class=\"fig-list\"><li>Fehlt ein passender <code>ComEventGrant</code>, wird der Zugriff verweigert: <code>ara::com</code> schlägt mit einem entsprechenden Fehlercode (z. B. <code>kGrantEnforcementFailed</code> bzw. Zugriffsverweigerung) fehl, und es erfolgt ein Security-Event-Logging via DLT/IAM.\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Zweistufiges Design- vs. Deployment-Pattern:</strong>\n<ul class=\"fig-list\"><li>Architekten definieren Berechtigungen zunächst abstrakt (<code>ComEventGrantDesign</code> verknüpft mit <code>ProcessDesign</code>), während System-Integratoren die verbindlichen Laufzeit-Rechte über <code>ComEventGrant</code> mit harter Bindung an <code>AdaptivePlatformServiceInstance</code> und <code>ServiceEventDeployment</code> (<code>TPS_MANI_01240</code>) konfigurieren.\n</li></ul>\n</li><li><strong>Konfigurationsfalle (Silent Failure / Denial of Service):</strong>\n<ul class=\"fig-list\"><li>Ist in einer Adaptive-Umgebung das IAM aktiv, führt das Fehlen des <code>ComEventGrant</code> im Manifest dazu, dass Event-Subscriptions trotz korrekt konfigurierter Netzwerkanbindung (SOME/IP Deployment) und übereinstimmender Instance-IDs auf Betriebssystem-/Middleware-Ebene blockiert werden.\n</li></ul>\n</li><li><strong>Eindeutigkeit der Bindung (Kardinalität <code>1</code>):</strong>\n<ul class=\"fig-list\"><li>Jeder <code>ComEventGrant</code> bindet exakt <em>eine</em> <code>AdaptivePlatformServiceInstance</code> an genau <em>ein</em> <code>ServiceEventDeployment</code>. Wildcards sind metamodellseitig nicht zulässig; jedes autorisierte Event muss explizit instantiiert werden.\n</li></ul>\n</li><li><strong>Port-Mapping-Konsistenz:</strong>\n<ul class=\"fig-list\"><li>Integratoren müssen sicherstellen, dass die über <code>ComEventGrant</code> autorisierte <code>AdaptivePlatformServiceInstance</code> konsistent über <code>ServiceInstanceToPortPrototypeMapping</code> dem <code>PortPrototype</code> des Prozesses zugeordnet ist, um Diskrepanzen zwischen IPC-Endpunkten und IAM-Policys zu verhindern.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-5f75bd1c8fb50021", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-2.0-Metamodell-Klassendiagramm (M2-Ebene nach AUTOSAR-Metamodell-Architektur).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP), Teilspezifikation <em>Manifest Specification</em> (<code>AUTOSAR_TPS_ManifestSpecification</code>, Release R20-11).\n</li><li><strong>Funktionaler Zweck:</strong> Modellierung der Zugriffsberechtigungen für Kommunikations-Events im Rahmen des <em>Identity and Access Management</em> (IAM) und des <em>Communication Management</em> (<code>ara::com</code>). Es definiert die formalen Beziehungen zur Gewährung von Zugriffsrechten (<code>ComEventGrant</code> als Spezialisierung von <code>ComGrant</code>) auf Instanz- und Deployment-Ebene sowie deren Entsprechung im Software-Design (<code>ComEventGrantDesign</code> als Spezialisierung von <code>ComGrantDesign</code>) gemäß den Anforderungen <code>RS_MANI_00060</code> und <code>TPS_MANI_01240</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen &amp; Stereotypen</h5>\n<ul class=\"fig-list\"><li><strong><code>ComGrant</code></strong> (Spezialisierung von <code>Grant</code>):\n<ul class=\"fig-list\"><li>Abstrakte Zwischenklasse für Kommunikations-Grants.\n</li><li>Assoziationen:\n<ul class=\"fig-list\"><li><code>+serviceInstance</code>: Referenziert genau eine (<code>[1]</code>) Instanz von <code>AdaptivePlatformServiceInstance</code>.\n</li><li><code>+remoteSubject</code>: Referenziert <code>0..*</code> entfernte IAM-Subjekte vom Typ <code>AbstractIamRemoteSubject</code>.\n</li></ul>\n</li></ul>\n</li><li><strong><code>ComEventGrant</code></strong> (Spezialisierung von <code>ComGrant</code>):\n<ul class=\"fig-list\"><li>Konkretes Deployment-Artefakt zur Freigabe des Zugriffs auf ein bestimmtes Event einer Service-Instanz.\n</li><li>Assoziationen:\n<ul class=\"fig-list\"><li><code>+serviceDeployment</code>: Referenziert genau ein (<code>[1]</code>) Event-Deployment <code>ServiceEventDeployment</code>.\n</li><li><code>+design</code> (<code>«atpUriDef»</code>): Optionale Referenz (<code>[0..1]</code>) auf das korrespondierende Entwurfsartefakt <code>ComEventGrantDesign</code>.\n</li></ul>\n</li></ul>\n</li><li><strong><code>AbstractIamRemoteSubject</code></strong> (<code>ARElement</code>):\n<ul class=\"fig-list\"><li>Repräsentiert ein entferntes Kommunikationssubjekt für die IAM-Autorisierung.\n</li></ul>\n</li><li><strong><code>ComGrantDesign</code></strong> (Spezialisierung von <code>GrantDesign</code>):\n<ul class=\"fig-list\"><li>Abstrakte Basisklasse für Entwurfszeit-Kommunikations-Grants.\n</li></ul>\n</li><li><strong><code>ComEventGrantDesign</code></strong> (Spezialisierung von <code>ComGrantDesign</code>):\n<ul class=\"fig-list\"><li>Entwurfszeit-Pendant zur Spezifikation von Berechtigungen auf Software-Architekturebene unabhängig vom konkreten Deployment.\n</li></ul>\n</li><li><strong><code>GrantDesign</code></strong> (<code>ARElement</code>):\n<ul class=\"fig-list\"><li>Abstrakte Basisklasse für Design-Grants.\n</li><li>Assoziation: Referenziert über <code>+processDesign</code> optional (<code>[0..1]</code>) ein <code>ProcessDesign</code>.\n</li></ul>\n</li><li><strong><code>ProcessDesign</code></strong> (<code>ARElement</code>):\n<ul class=\"fig-list\"><li>Repräsentiert den Prozessentwurf auf Architekturebene.\n</li><li>Wird referenziert von:\n<ul class=\"fig-list\"><li><code>Process</code> über Rolle <code>+design [0..1]</code>.\n</li><li><code>ServiceInstanceToPortPrototypeMapping</code> über Rolle <code>+processDesign [0..1]</code> (<code>«atpUriDef»</code>).\n</li></ul>\n</li></ul>\n</li><li><strong><code>Process</code></strong> (Spezialisierung von <code>AbstractExecutionContext</code>):\n<ul class=\"fig-list\"><li>Repräsentiert die konkrete OS-Prozessinstanz zur Laufzeit.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>functionClusterAffiliation: String [0..1]</code>\n</li><li><code>numberOfRestartAttempts: PositiveInteger [0..1]</code>\n</li><li><code>preMapping: Boolean [0..1]</code>\n</li></ul>\n</li></ul>\n</li><li><strong><code>AdaptivePlatformServiceInstance</code></strong> (<code>UploadablePackageElement</code>):\n<ul class=\"fig-list\"><li>Repräsentiert eine konkrete (bereitgestellte oder konsumierte) Service-Instanz auf der Adaptive Platform.\n</li><li>Assoziation: Referenziert über <code>+serviceInterfaceDeployment</code> optional (<code>[0..1]</code>) ein <code>ServiceInterfaceDeployment</code>.\n</li></ul>\n</li><li><strong><code>ServiceInterfaceDeployment</code></strong> (<code>UploadablePackageElement</code>):\n<ul class=\"fig-list\"><li>Protokollspezifische Bindung eines Service-Interfaces (z. B. SOME/IP).\n</li><li>Komposition (schwarze Raute): Aggregiert <code>0..*</code> <code>ServiceEventDeployment</code>-Elemente über die Rolle <code>+eventDeployment</code>.\n</li></ul>\n</li><li><strong><code>ServiceEventDeployment</code></strong> (<code>Identifiable</code>):\n<ul class=\"fig-list\"><li>Transport- und serialisierungsspezifisches Deployment eines einzelnen Events (z. B. SOME/IP Event ID, Event Groups).\n</li></ul>\n</li><li><strong><code>ServiceInstanceToPortPrototypeMapping</code></strong> (<code>UploadablePackageElement</code>):\n<ul class=\"fig-list\"><li>Verknüpft Ports mit Service-Instanzen und Prozessen.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>enablesLogTrace: Boolean [0..1]</code>\n</li></ul>\n</li><li>Assoziationen:\n<ul class=\"fig-list\"><li><code>+process</code> (<code>«atpSplitable»</code>): Referenziert optional (<code>[0..1]</code>) einen <code>Process</code>.\n</li><li><code>+processDesign</code> (<code>«atpUriDef»</code>): Referenziert optional (<code>[0..1]</code>) ein <code>ProcessDesign</code>.\n</li><li><code>+serviceInstance</code>: Referenziert optional (<code>[0..1]</code>) eine <code>AdaptivePlatformServiceInstance</code>.\n</li><li><code>+portPrototype</code> (<code>«instanceRef,atpUriDef»</code>): Instanzreferenz (<code>[0..1]</code>) auf einen <code>PortPrototype</code>.\n</li></ul>\n</li></ul>\n</li><li><strong><code>PortPrototype</code></strong> (<code>AtpBlueprintable</code>, <code>AtpPrototype</code>):\n<ul class=\"fig-list\"><li>Architektureller Kommunikationsendpunkt (RPort/PPort) einer Software-Komponente.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell für den Manifest-Entwurf handelt, existiert kein Sequenzdiagramm; das Diagramm determiniert jedoch zwingend folgende Laufzeitabläufe im AP IAM- und IPC-Stack:</p>\n<ol class=\"fig-list\"><li><strong>Deployment- &amp; Startphase (Execution Management):</strong>\n<ul class=\"fig-list\"><li>Beim Parsen des <em>Execution Manifests</em> und des <em>Service Instance Manifests</em> erzeugt die IAM-Instanz Zugriffskontrolltabellen (ACLs / Capabilities) für den jeweiligen <code>Process</code>.\n</li></ul>\n</li><li><strong>Access Control Check (<code>ara::com</code> Subscription/FindService):</strong>\n<ul class=\"fig-list\"><li>Ruft eine Applikation innerhalb eines Prozesses Methoden wie <code>FindService()</code>, <code>Subscribe()</code> oder <code>Send()</code> für ein Event auf, fängt der Middleware-Stack (<code>ara::com</code>) bzw. der IAM-Policy-Enforcement-Point (PEP) die Anfrage ab.\n</li></ul>\n</li><li><strong>Validierungspfad:</strong>\n<ul class=\"fig-list\"><li>Der PEP prüft, ob die Prozess-ID/UID über das Mapping (<code>ServiceInstanceToPortPrototypeMapping</code> → <code>AdaptivePlatformServiceInstance</code>) eine explizite <code>ComEventGrant</code>-Freigabe für das konkrete <code>ServiceEventDeployment</code> besitzt.\n</li></ul>\n</li><li><strong>Fehlerpfad &amp; Abbruchbedingung:</strong>\n<ul class=\"fig-list\"><li>Fehlt ein passender <code>ComEventGrant</code>, wird der Zugriff verweigert: <code>ara::com</code> schlägt mit einem entsprechenden Fehlercode (z. B. <code>kGrantEnforcementFailed</code> bzw. Zugriffsverweigerung) fehl, und es erfolgt ein Security-Event-Logging via DLT/IAM.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Zweistufiges Design- vs. Deployment-Pattern:</strong>\n<ul class=\"fig-list\"><li>Architekten definieren Berechtigungen zunächst abstrakt (<code>ComEventGrantDesign</code> via <code>ComGrantDesign</code> verknüpft mit <code>ProcessDesign</code>), während System-Integratoren die verbindlichen Laufzeit-Rechte über <code>ComEventGrant</code> (spezialisiert von <code>ComGrant</code>) mit Bindung an <code>AdaptivePlatformServiceInstance</code> und <code>ServiceEventDeployment</code> konfigurieren.\n</li></ul>\n</li><li><strong>Einführung von ComGrant und Remote Subjects:</strong>\n<ul class=\"fig-list\"><li>Durch die Zwischenklasse <code>ComGrant</code> wird die Bindung an <code>AdaptivePlatformServiceInstance</code> verallgemeinert und um <code>AbstractIamRemoteSubject</code> (<code>+remoteSubject [0..*]</code>) erweitert, um IAM-Prüfungen für netzwerkübergreifende bzw. externe Kommunikationspartner zu unterstützen.\n</li></ul>\n</li><li><strong>Konfigurationsfalle (Silent Failure / Denial of Service):</strong>\n<ul class=\"fig-list\"><li>Ist in einer Adaptive-Umgebung das IAM aktiv, führt das Fehlen des passenden Grants im Manifest dazu, dass Event-Subscriptions trotz korrekt konfigurierter Netzwerkanbindung auf Middleware-Ebene blockiert werden.\n</li></ul>\n</li><li><strong>Eindeutigkeit der Bindung (Kardinalität <code>1</code>):</strong>\n<ul class=\"fig-list\"><li><code>ComGrant</code> bindet genau eine (<code>[1]</code>) <code>AdaptivePlatformServiceInstance</code> und <code>ComEventGrant</code> genau ein (<code>[1]</code>) <code>ServiceEventDeployment</code>.\n</li></ul>\n</li><li><strong>Port-Mapping-Konsistenz:</strong>\n<ul class=\"fig-list\"><li>Integratoren müssen sicherstellen, dass die über <code>ComGrant</code> autorisierte <code>AdaptivePlatformServiceInstance</code> konsistent über <code>ServiceInstanceToPortPrototypeMapping</code> dem <code>PortPrototype</code> des Prozesses zugeordnet ist.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-b061eeea61480361", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-2.0-Metamodell-Klassendiagramm (M2-Ebene nach AUTOSAR-Metamodell-Architektur).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP), Teilspezifikation <em>Manifest Specification</em> (<code>AUTOSAR_TPS_ManifestSpecification</code>, Release R21-11).\n</li><li><strong>Funktionaler Zweck:</strong> Modellierung der Zugriffsberechtigungen für Kommunikations-Events im Rahmen des <em>Identity and Access Management</em> (IAM) und des <em>Communication Management</em> (<code>ara::com</code>). Es definiert die formalen Beziehungen zur Gewährung von Zugriffsrechten (<code>ComEventGrant</code> als Spezialisierung von <code>ComGrant</code>) auf Instanz- und Deployment-Ebene sowie deren Entsprechung im Software-Design (<code>ComEventGrantDesign</code> als Spezialisierung von <code>ComGrantDesign</code>) gemäß den Anforderungen <code>RS_MANI_00060</code> und <code>TPS_MANI_01240</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen &amp; Stereotypen</h5>\n<ul class=\"fig-list\"><li><strong><code>ComGrant</code></strong> (Spezialisierung von <code>Grant</code>):\n<ul class=\"fig-list\"><li>Abstrakte Zwischenklasse für Kommunikations-Grants.\n</li><li>Assoziationen:\n<ul class=\"fig-list\"><li><code>+serviceInstance</code>: Referenziert genau eine (<code>[1]</code>) Instanz von <code>AdaptivePlatformServiceInstance</code>.\n</li><li><code>+remoteSubject</code>: Referenziert <code>0..*</code> entfernte IAM-Subjekte vom Typ <code>AbstractIamRemoteSubject</code>.\n</li></ul>\n</li></ul>\n</li><li><strong><code>ComEventGrant</code></strong> (Spezialisierung von <code>ComGrant</code>):\n<ul class=\"fig-list\"><li>Konkretes Deployment-Artefakt zur Freigabe des Zugriffs auf ein bestimmtes Event einer Service-Instanz.\n</li><li>Assoziationen:\n<ul class=\"fig-list\"><li><code>+serviceDeployment</code>: Referenziert genau ein (<code>[1]</code>) Event-Deployment <code>ServiceEventDeployment</code>.\n</li><li><code>+design</code> (<code>«atpUriDef»</code>): Optionale Referenz (<code>[0..1]</code>) auf das korrespondierende Entwurfsartefakt <code>ComEventGrantDesign</code>.\n</li></ul>\n</li></ul>\n</li><li><strong><code>AbstractIamRemoteSubject</code></strong> (<code>ARElement</code>):\n<ul class=\"fig-list\"><li>Repräsentiert ein entferntes Kommunikationssubjekt für die IAM-Autorisierung.\n</li></ul>\n</li><li><strong><code>ComGrantDesign</code></strong> (Spezialisierung von <code>GrantDesign</code>):\n<ul class=\"fig-list\"><li>Abstrakte Basisklasse für Entwurfszeit-Kommunikations-Grants.\n</li></ul>\n</li><li><strong><code>ComEventGrantDesign</code></strong> (Spezialisierung von <code>ComGrantDesign</code>):\n<ul class=\"fig-list\"><li>Entwurfszeit-Pendant zur Spezifikation von Berechtigungen auf Software-Architekturebene unabhängig vom konkreten Deployment.\n</li></ul>\n</li><li><strong><code>GrantDesign</code></strong> (<code>ARElement</code>):\n<ul class=\"fig-list\"><li>Abstrakte Basisklasse für Design-Grants.\n</li><li>Assoziation: Referenziert über <code>+processDesign</code> optional (<code>[0..1]</code>) ein <code>ProcessDesign</code>.\n</li></ul>\n</li><li><strong><code>ProcessDesign</code></strong> (<code>ARElement</code>):\n<ul class=\"fig-list\"><li>Repräsentiert den Prozessentwurf auf Architekturebene.\n</li><li>Wird referenziert von:\n<ul class=\"fig-list\"><li><code>Process</code> über Rolle <code>+design [0..1]</code>.\n</li><li><code>ServiceInstanceToPortPrototypeMapping</code> über Rolle <code>+processDesign [0..1]</code> (<code>«atpUriDef»</code>).\n</li></ul>\n</li></ul>\n</li><li><strong><code>Process</code></strong> (Spezialisierung von <code>AbstractExecutionContext</code>):\n<ul class=\"fig-list\"><li>Repräsentiert die konkrete OS-Prozessinstanz zur Laufzeit.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>functionClusterAffiliation: String [0..1]</code>\n</li><li><code>numberOfRestartAttempts: PositiveInteger [0..1]</code>\n</li><li><code>preMapping: Boolean [0..1]</code>\n</li></ul>\n</li></ul>\n</li><li><strong><code>AdaptivePlatformServiceInstance</code></strong> (<code>UploadablePackageElement</code>):\n<ul class=\"fig-list\"><li>Repräsentiert eine konkrete (bereitgestellte oder konsumierte) Service-Instanz auf der Adaptive Platform.\n</li><li>Assoziation: Referenziert über <code>+serviceInterfaceDeployment</code> optional (<code>[0..1]</code>) ein <code>ServiceInterfaceDeployment</code>.\n</li></ul>\n</li><li><strong><code>ServiceInterfaceDeployment</code></strong> (<code>UploadablePackageElement</code>):\n<ul class=\"fig-list\"><li>Protokollspezifische Bindung eines Service-Interfaces (z. B. SOME/IP).\n</li><li>Komposition (schwarze Raute): Aggregiert <code>0..*</code> <code>ServiceEventDeployment</code>-Elemente über die Rolle <code>+eventDeployment</code>.\n</li></ul>\n</li><li><strong><code>ServiceEventDeployment</code></strong> (<code>Identifiable</code>):\n<ul class=\"fig-list\"><li>Transport- und serialisierungsspezifisches Deployment eines einzelnen Events (z. B. SOME/IP Event ID, Event Groups).\n</li></ul>\n</li><li><strong><code>ServiceInstanceToPortPrototypeMapping</code></strong> (<code>UploadablePackageElement</code>):\n<ul class=\"fig-list\"><li>Verknüpft Ports mit Service-Instanzen und Prozessen (ohne Attribute).\n</li><li>Assoziationen:\n<ul class=\"fig-list\"><li><code>+process</code> (<code>«atpSplitable»</code>): Referenziert optional (<code>[0..1]</code>) einen <code>Process</code>.\n</li><li><code>+processDesign</code> (<code>«atpUriDef»</code>): Referenziert optional (<code>[0..1]</code>) ein <code>ProcessDesign</code>.\n</li><li><code>+serviceInstance</code>: Referenziert optional (<code>[0..1]</code>) eine <code>AdaptivePlatformServiceInstance</code>.\n</li><li><code>+portPrototype</code> (<code>«instanceRef,atpUriDef»</code>): Instanzreferenz (<code>[0..1]</code>) auf einen <code>PortPrototype</code>.\n</li></ul>\n</li></ul>\n</li><li><strong><code>PortPrototype</code></strong> (<code>AtpBlueprintable</code>, <code>AtpPrototype</code>):\n<ul class=\"fig-list\"><li>Architektureller Kommunikationsendpunkt (RPort/PPort) einer Software-Komponente.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell für den Manifest-Entwurf handelt, existiert kein Sequenzdiagramm; das Diagramm determiniert jedoch zwingend folgende Laufzeitabläufe im AP IAM- und IPC-Stack:</p>\n<ol class=\"fig-list\"><li><strong>Deployment- &amp; Startphase (Execution Management):</strong>\n<ul class=\"fig-list\"><li>Beim Parsen des <em>Execution Manifests</em> und des <em>Service Instance Manifests</em> erzeugt die IAM-Instanz Zugriffskontrolltabellen (ACLs / Capabilities) für den jeweiligen <code>Process</code>.\n</li></ul>\n</li><li><strong>Access Control Check (<code>ara::com</code> Subscription/FindService):</strong>\n<ul class=\"fig-list\"><li>Ruft eine Applikation innerhalb eines Prozesses Methoden wie <code>FindService()</code>, <code>Subscribe()</code> oder <code>Send()</code> für ein Event auf, fängt der Middleware-Stack (<code>ara::com</code>) bzw. der IAM-Policy-Enforcement-Point (PEP) die Anfrage ab.\n</li></ul>\n</li><li><strong>Validierungspfad:</strong>\n<ul class=\"fig-list\"><li>Der PEP prüft, ob die Prozess-ID/UID über das Mapping (<code>ServiceInstanceToPortPrototypeMapping</code> → <code>AdaptivePlatformServiceInstance</code>) eine explizite <code>ComEventGrant</code>-Freigabe für das konkrete <code>ServiceEventDeployment</code> besitzt.\n</li></ul>\n</li><li><strong>Fehlerpfad &amp; Abbruchbedingung:</strong>\n<ul class=\"fig-list\"><li>Fehlt ein passender <code>ComEventGrant</code>, wird der Zugriff verweigert: <code>ara::com</code> schlägt mit einem entsprechenden Fehlercode (z. B. <code>kGrantEnforcementFailed</code> bzw. Zugriffsverweigerung) fehl, und es erfolgt ein Security-Event-Logging via DLT/IAM.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Zweistufiges Design- vs. Deployment-Pattern:</strong>\n<ul class=\"fig-list\"><li>Architekten definieren Berechtigungen zunächst abstrakt (<code>ComEventGrantDesign</code> via <code>ComGrantDesign</code> verknüpft mit <code>ProcessDesign</code>), während System-Integratoren die verbindlichen Laufzeit-Rechte über <code>ComEventGrant</code> (spezialisiert von <code>ComGrant</code>) mit Bindung an <code>AdaptivePlatformServiceInstance</code> und <code>ServiceEventDeployment</code> konfigurieren.\n</li></ul>\n</li><li><strong>Einführung von ComGrant und Remote Subjects:</strong>\n<ul class=\"fig-list\"><li>Durch die Zwischenklasse <code>ComGrant</code> wird die Bindung an <code>AdaptivePlatformServiceInstance</code> verallgemeinert und um <code>AbstractIamRemoteSubject</code> (<code>+remoteSubject [0..*]</code>) erweitert, um IAM-Prüfungen für netzwerkübergreifende bzw. externe Kommunikationspartner zu unterstützen.\n</li></ul>\n</li><li><strong>Konfigurationsfalle (Silent Failure / Denial of Service):</strong>\n<ul class=\"fig-list\"><li>Ist in einer Adaptive-Umgebung das IAM aktiv, führt das Fehlen des passenden Grants im Manifest dazu, dass Event-Subscriptions trotz korrekt konfigurierter Netzwerkanbindung auf Middleware-Ebene blockiert werden.\n</li></ul>\n</li><li><strong>Eindeutigkeit der Bindung (Kardinalität <code>1</code>):</strong>\n<ul class=\"fig-list\"><li><code>ComGrant</code> bindet genau eine (<code>[1]</code>) <code>AdaptivePlatformServiceInstance</code> und <code>ComEventGrant</code> genau ein (<code>[1]</code>) <code>ServiceEventDeployment</code>.\n</li></ul>\n</li><li><strong>Port-Mapping-Konsistenz:</strong>\n<ul class=\"fig-list\"><li>Integratoren müssen sicherstellen, dass die über <code>ComGrant</code> autorisierte <code>AdaptivePlatformServiceInstance</code> konsistent über <code>ServiceInstanceToPortPrototypeMapping</code> dem <code>PortPrototype</code> des Prozesses zugeordnet ist.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-9baeaafcf15f8dd8", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-2.0-Metamodell-Klassendiagramm (M2-Ebene nach AUTOSAR-Metamodell-Architektur).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP), Teilspezifikation <em>Manifest Specification</em> (<code>AUTOSAR_TPS_ManifestSpecification</code>, Release R22-11).\n</li><li><strong>Funktionaler Zweck:</strong> Modellierung der Zugriffsberechtigungen für Kommunikations-Events im Rahmen des <em>Identity and Access Management</em> (IAM) und des <em>Communication Management</em> (<code>ara::com</code>). Es definiert die formalen Beziehungen zur Gewährung von Zugriffsrechten (<code>ComEventGrant</code> als Spezialisierung von <code>ComGrant</code>) auf Instanz- und Deployment-Ebene sowie deren Entsprechung im Software-Design (<code>ComEventGrantDesign</code> als Spezialisierung von <code>ComGrantDesign</code>) gemäß den Anforderungen <code>RS_MANI_00060</code> und <code>TPS_MANI_01240</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen &amp; Stereotypen</h5>\n<ul class=\"fig-list\"><li><strong><code>ComGrant</code></strong> (Spezialisierung von <code>Grant</code>):\n<ul class=\"fig-list\"><li>Abstrakte Zwischenklasse für Kommunikations-Grants.\n</li><li>Assoziationen:\n<ul class=\"fig-list\"><li><code>+serviceInstance</code>: Referenziert optional (<code>[0..1]</code>) eine <code>AdaptivePlatformServiceInstance</code>.\n</li><li><code>+remoteSubject</code>: Referenziert <code>0..*</code> entfernte IAM-Subjekte vom Typ <code>AbstractIamRemoteSubject</code>.\n</li></ul>\n</li></ul>\n</li><li><strong><code>ComEventGrant</code></strong> (Spezialisierung von <code>ComGrant</code>):\n<ul class=\"fig-list\"><li>Konkretes Deployment-Artefakt zur Freigabe des Zugriffs auf ein bestimmtes Event einer Service-Instanz.\n</li><li>Assoziationen:\n<ul class=\"fig-list\"><li><code>+serviceDeployment</code>: Referenziert optional (<code>[0..1]</code>) ein Event-Deployment <code>ServiceEventDeployment</code>.\n</li><li><code>+design</code> (<code>«atpUriDef»</code>): Optionale Referenz (<code>[0..1]</code>) auf das korrespondierende Entwurfsartefakt <code>ComEventGrantDesign</code>.\n</li></ul>\n</li></ul>\n</li><li><strong><code>AbstractIamRemoteSubject</code></strong> (<code>ARElement</code>):\n<ul class=\"fig-list\"><li>Repräsentiert ein entferntes Kommunikationssubjekt für die IAM-Autorisierung.\n</li></ul>\n</li><li><strong><code>ComGrantDesign</code></strong> (Spezialisierung von <code>GrantDesign</code>):\n<ul class=\"fig-list\"><li>Abstrakte Basisklasse für Entwurfszeit-Kommunikations-Grants.\n</li></ul>\n</li><li><strong><code>ComEventGrantDesign</code></strong> (Spezialisierung von <code>ComGrantDesign</code>):\n<ul class=\"fig-list\"><li>Entwurfszeit-Pendant zur Spezifikation von Berechtigungen auf Software-Architekturebene unabhängig vom konkreten Deployment.\n</li></ul>\n</li><li><strong><code>GrantDesign</code></strong> (<code>ARElement</code>):\n<ul class=\"fig-list\"><li>Abstrakte Basisklasse für Design-Grants.\n</li><li>Assoziation: Referenziert über <code>+processDesign</code> optional (<code>[0..1]</code>) ein <code>ProcessDesign</code>.\n</li></ul>\n</li><li><strong><code>ProcessDesign</code></strong> (<code>ARElement</code>):\n<ul class=\"fig-list\"><li>Repräsentiert den Prozessentwurf auf Architekturebene.\n</li><li>Wird referenziert von:\n<ul class=\"fig-list\"><li><code>Process</code> über Rolle <code>+design [0..1]</code>.\n</li><li><code>ServiceInstanceToPortPrototypeMapping</code> über Rolle <code>+processDesign [0..1]</code> (<code>«atpUriDef»</code>).\n</li></ul>\n</li></ul>\n</li><li><strong><code>Process</code></strong> (Spezialisierung von <code>AbstractExecutionContext</code>):\n<ul class=\"fig-list\"><li>Repräsentiert die konkrete OS-Prozessinstanz zur Laufzeit (ohne explizit dargestellte Attribute).\n</li></ul>\n</li><li><strong><code>AdaptivePlatformServiceInstance</code></strong> (<code>UploadablePackageElement</code>):\n<ul class=\"fig-list\"><li>Repräsentiert eine konkrete (bereitgestellte oder konsumierte) Service-Instanz auf der Adaptive Platform.\n</li><li>Assoziation: Referenziert über <code>+serviceInterfaceDeployment</code> optional (<code>[0..1]</code>) ein <code>ServiceInterfaceDeployment</code>.\n</li></ul>\n</li><li><strong><code>ServiceInterfaceDeployment</code></strong> (<code>UploadablePackageElement</code>):\n<ul class=\"fig-list\"><li>Protokollspezifische Bindung eines Service-Interfaces (z. B. SOME/IP).\n</li><li>Komposition (schwarze Raute): Aggregiert <code>0..*</code> <code>ServiceEventDeployment</code>-Elemente über die Rolle <code>+eventDeployment</code>.\n</li></ul>\n</li><li><strong><code>ServiceEventDeployment</code></strong> (<code>Identifiable</code>):\n<ul class=\"fig-list\"><li>Transport- und serialisierungsspezifisches Deployment eines einzelnen Events (z. B. SOME/IP Event ID, Event Groups).\n</li></ul>\n</li><li><strong><code>ServiceInstanceToPortPrototypeMapping</code></strong> (<code>UploadablePackageElement</code>):\n<ul class=\"fig-list\"><li>Verknüpft Ports mit Service-Instanzen und Prozessen.\n</li><li>Assoziationen:\n<ul class=\"fig-list\"><li><code>+process</code> (<code>«atpSplitable»</code>): Referenziert optional (<code>[0..1]</code>) einen <code>Process</code>.\n</li><li><code>+processDesign</code> (<code>«atpUriDef»</code>): Referenziert optional (<code>[0..1]</code>) ein <code>ProcessDesign</code>.\n</li><li><code>+serviceInstance</code>: Referenziert optional (<code>[0..1]</code>) eine <code>AdaptivePlatformServiceInstance</code>.\n</li><li><code>+portPrototype</code> (<code>«instanceRef,atpUriDef»</code>): Instanzreferenz (<code>[0..1]</code>) auf einen <code>PortPrototype</code>.\n</li></ul>\n</li></ul>\n</li><li><strong><code>PortPrototype</code></strong> (<code>AtpBlueprintable</code>, <code>AtpPrototype</code>):\n<ul class=\"fig-list\"><li>Architektureller Kommunikationsendpunkt (RPort/PPort) einer Software-Komponente.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell für den Manifest-Entwurf handelt, existiert kein Sequenzdiagramm; das Diagramm determiniert jedoch zwingend folgende Laufzeitabläufe im AP IAM- und IPC-Stack:</p>\n<ol class=\"fig-list\"><li><strong>Deployment- &amp; Startphase (Execution Management):</strong>\n<ul class=\"fig-list\"><li>Beim Parsen des <em>Execution Manifests</em> und des <em>Service Instance Manifests</em> erzeugt die IAM-Instanz Zugriffskontrolltabellen (ACLs / Capabilities) für den jeweiligen <code>Process</code>.\n</li></ul>\n</li><li><strong>Access Control Check (<code>ara::com</code> Subscription/FindService):</strong>\n<ul class=\"fig-list\"><li>Ruft eine Applikation innerhalb eines Prozesses Methoden wie <code>FindService()</code>, <code>Subscribe()</code> oder <code>Send()</code> für ein Event auf, fängt der Middleware-Stack (<code>ara::com</code>) bzw. der IAM-Policy-Enforcement-Point (PEP) die Anfrage ab.\n</li></ul>\n</li><li><strong>Validierungspfad:</strong>\n<ul class=\"fig-list\"><li>Der PEP prüft, ob die Prozess-ID/UID über das Mapping (<code>ServiceInstanceToPortPrototypeMapping</code> → <code>AdaptivePlatformServiceInstance</code>) eine explizite <code>ComEventGrant</code>-Freigabe für das konkrete <code>ServiceEventDeployment</code> besitzt.\n</li></ul>\n</li><li><strong>Fehlerpfad &amp; Abbruchbedingung:</strong>\n<ul class=\"fig-list\"><li>Fehlt ein passender <code>ComEventGrant</code>, wird der Zugriff verweigert: <code>ara::com</code> schlägt mit einem entsprechenden Fehlercode (z. B. <code>kGrantEnforcementFailed</code> bzw. Zugriffsverweigerung) fehl, und es erfolgt ein Security-Event-Logging via DLT/IAM.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Zweistufiges Design- vs. Deployment-Pattern:</strong>\n<ul class=\"fig-list\"><li>Architekten definieren Berechtigungen zunächst abstrakt (<code>ComEventGrantDesign</code> via <code>ComGrantDesign</code> verknüpft mit <code>ProcessDesign</code>), während System-Integratoren die verbindlichen Laufzeit-Rechte über <code>ComEventGrant</code> (spezialisiert von <code>ComGrant</code>) konfigurieren.\n</li></ul>\n</li><li><strong>Optionale Kardinalitäten (<code>0..1</code>):</strong>\n<ul class=\"fig-list\"><li>Die Assoziationen <code>+serviceInstance</code> (an <code>ComGrant</code>) und <code>+serviceDeployment</code> (an <code>ComEventGrant</code>) besitzen nun die Kardinalität <code>0..1</code> statt zuvor strikt <code>1</code>. Dies gestattet flexiblere Konstellationen bei der schrittweisen Modellierung oder partiellen Autorisierung von Service- und Event-Deployments.\n</li></ul>\n</li><li><strong>Konfigurationsfalle (Silent Failure / Denial of Service):</strong>\n<ul class=\"fig-list\"><li>Ist in einer Adaptive-Umgebung das IAM aktiv, führt das Fehlen des passenden Grants im Manifest dazu, dass Event-Subscriptions trotz korrekt konfigurierter Netzwerkanbindung auf Middleware-Ebene blockiert werden.\n</li></ul>\n</li><li><strong>Port-Mapping-Konsistenz:</strong>\n<ul class=\"fig-list\"><li>Integratoren müssen sicherstellen, dass die über <code>ComGrant</code> autorisierte <code>AdaptivePlatformServiceInstance</code> konsistent über <code>ServiceInstanceToPortPrototypeMapping</code> dem <code>PortPrototype</code> des Prozesses zugeordnet ist.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-2cbd2bea127981b1", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-2.0-Metamodell-Klassendiagramm (M2-Ebene nach AUTOSAR-Metamodell-Architektur).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP), Teilspezifikation <em>Manifest Specification</em> (<code>AUTOSAR_TPS_ManifestSpecification</code>, Release R23-11).\n</li><li><strong>Funktionaler Zweck:</strong> Modellierung der Zugriffsberechtigungen für Kommunikations-Events im Rahmen des <em>Identity and Access Management</em> (IAM) und des <em>Communication Management</em> (<code>ara::com</code>). Es definiert die formalen Beziehungen zur Gewährung von Zugriffsrechten (<code>ComEventGrant</code> als Spezialisierung von <code>ComGrant</code>) auf Instanz- und Deployment-Ebene sowie deren Entsprechung im Software-Design (<code>ComEventGrantDesign</code> als Spezialisierung von <code>ComGrantDesign</code>) gemäß den Anforderungen <code>RS_MANI_00060</code> und <code>TPS_MANI_01240</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen &amp; Stereotypen</h5>\n<ul class=\"fig-list\"><li><strong><code>ComGrant</code></strong> (Spezialisierung von <code>Grant</code>):\n<ul class=\"fig-list\"><li>Abstrakte Zwischenklasse für Kommunikations-Grants.\n</li><li>Assoziationen:\n<ul class=\"fig-list\"><li><code>+serviceInstance</code>: Referenziert optional (<code>[0..1]</code>) eine <code>AdaptivePlatformServiceInstance</code>.\n</li><li><code>+remoteSubject</code>: Referenziert <code>0..*</code> entfernte IAM-Subjekte vom Typ <code>AbstractIamRemoteSubject</code>.\n</li></ul>\n</li></ul>\n</li><li><strong><code>ComEventGrant</code></strong> (Spezialisierung von <code>ComGrant</code>):\n<ul class=\"fig-list\"><li>Konkretes Deployment-Artefakt zur Freigabe des Zugriffs auf ein bestimmtes Event einer Service-Instanz.\n</li><li>Assoziationen:\n<ul class=\"fig-list\"><li><code>+serviceDeployment</code>: Referenziert optional (<code>[0..1]</code>) ein Event-Deployment <code>ServiceEventDeployment</code>.\n</li><li><code>+design</code> (<code>«atpUriDef»</code>): Optionale Referenz (<code>[0..1]</code>) auf das korrespondierende Entwurfsartefakt <code>ComEventGrantDesign</code>.\n</li></ul>\n</li></ul>\n</li><li><strong><code>AbstractIamRemoteSubject</code></strong> (<code>UploadableDeploymentElement</code>):\n<ul class=\"fig-list\"><li>Repräsentiert ein entferntes Kommunikationssubjekt für die IAM-Autorisierung als auslieferbares Deployment-Element.\n</li></ul>\n</li><li><strong><code>ComGrantDesign</code></strong> (Spezialisierung von <code>GrantDesign</code>):\n<ul class=\"fig-list\"><li>Abstrakte Basisklasse für Entwurfszeit-Kommunikations-Grants.\n</li></ul>\n</li><li><strong><code>ComEventGrantDesign</code></strong> (Spezialisierung von <code>ComGrantDesign</code>):\n<ul class=\"fig-list\"><li>Entwurfszeit-Pendant zur Spezifikation von Berechtigungen auf Software-Architekturebene unabhängig vom konkreten Deployment.\n</li></ul>\n</li><li><strong><code>GrantDesign</code></strong> (<code>ARElement</code>):\n<ul class=\"fig-list\"><li>Abstrakte Basisklasse für Design-Grants.\n</li><li>Assoziation: Referenziert über <code>+processDesign</code> optional (<code>[0..1]</code>) ein <code>ProcessDesign</code>.\n</li></ul>\n</li><li><strong><code>ProcessDesign</code></strong> (<code>ARElement</code>):\n<ul class=\"fig-list\"><li>Repräsentiert den Prozessentwurf auf Architekturebene.\n</li><li>Wird referenziert von:\n<ul class=\"fig-list\"><li><code>Process</code> über Rolle <code>+design [0..1]</code>.\n</li><li><code>ServiceInstanceToPortPrototypeMapping</code> über Rolle <code>+processDesign [0..1]</code> (<code>«atpUriDef»</code>).\n</li></ul>\n</li></ul>\n</li><li><strong><code>Process</code></strong> (Spezialisierung von <code>AbstractExecutionContext</code>):\n<ul class=\"fig-list\"><li>Repräsentiert die konkrete OS-Prozessinstanz zur Laufzeit.\n</li></ul>\n</li><li><strong><code>AdaptivePlatformServiceInstance</code></strong> (<code>UploadableDesignElement</code>):\n<ul class=\"fig-list\"><li>Repräsentiert eine Service-Instanz auf Design-Ebene.\n</li><li>Assoziation: Referenziert über <code>+serviceInterfaceDeployment</code> optional (<code>[0..1]</code>) ein <code>ServiceInterfaceDeployment</code>.\n</li></ul>\n</li><li><strong><code>ServiceInterfaceDeployment</code></strong> (<code>UploadableDesignElement</code>):\n<ul class=\"fig-list\"><li>Protokollspezifische Bindung eines Service-Interfaces auf Design-Ebene.\n</li><li>Komposition (schwarze Raute, <code>«atpVariation,atpSplitable»</code>): Aggregiert <code>0..*</code> <code>ServiceEventDeployment</code>-Elemente über die Rolle <code>+eventDeployment</code>.\n</li></ul>\n</li><li><strong><code>ServiceEventDeployment</code></strong> (<code>Identifiable</code>):\n<ul class=\"fig-list\"><li>Transport- und serialisierungsspezifisches Deployment eines einzelnen Events (z. B. SOME/IP Event ID, Event Groups).\n</li></ul>\n</li><li><strong><code>ServiceInstanceToPortPrototypeMapping</code></strong> (<code>UploadableDesignElement</code>):\n<ul class=\"fig-list\"><li>Verknüpft Ports mit Service-Instanzen und Prozessen auf Design-Ebene.\n</li><li>Assoziationen:\n<ul class=\"fig-list\"><li><code>+process</code> (<code>«atpSplitable»</code>): Referenziert optional (<code>[0..1]</code>) einen <code>Process</code>.\n</li><li><code>+processDesign</code> (<code>«atpUriDef»</code>): Referenziert optional (<code>[0..1]</code>) ein <code>ProcessDesign</code>.\n</li><li><code>+serviceInstance</code>: Referenziert optional (<code>[0..1]</code>) eine <code>AdaptivePlatformServiceInstance</code>.\n</li><li><code>+portPrototype</code> (<code>«instanceRef,atpUriDef»</code>): Instanzreferenz (<code>[0..1]</code>) auf einen <code>PortPrototype</code>.\n</li></ul>\n</li></ul>\n</li><li><strong><code>PortPrototype</code></strong> (<code>AtpBlueprintable</code>, <code>AtpPrototype</code>):\n<ul class=\"fig-list\"><li>Architektureller Kommunikationsendpunkt (RPort/PPort) einer Software-Komponente.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell für den Manifest-Entwurf handelt, existiert kein Sequenzdiagramm; das Diagramm determiniert jedoch zwingend folgende Laufzeitabläufe im AP IAM- und IPC-Stack:</p>\n<ol class=\"fig-list\"><li><strong>Deployment- &amp; Startphase (Execution Management):</strong>\n<ul class=\"fig-list\"><li>Beim Parsen des <em>Execution Manifests</em> und des <em>Service Instance Manifests</em> erzeugt die IAM-Instanz Zugriffskontrolltabellen (ACLs / Capabilities) für den jeweiligen <code>Process</code>.\n</li></ul>\n</li><li><strong>Access Control Check (<code>ara::com</code> Subscription/FindService):</strong>\n<ul class=\"fig-list\"><li>Ruft eine Applikation innerhalb eines Prozesses Methoden wie <code>FindService()</code>, <code>Subscribe()</code> oder <code>Send()</code> für ein Event auf, fängt der Middleware-Stack (<code>ara::com</code>) bzw. der IAM-Policy-Enforcement-Point (PEP) die Anfrage ab.\n</li></ul>\n</li><li><strong>Validierungspfad:</strong>\n<ul class=\"fig-list\"><li>Der PEP prüft, ob die Prozess-ID/UID über das Mapping (<code>ServiceInstanceToPortPrototypeMapping</code> → <code>AdaptivePlatformServiceInstance</code>) eine explizite <code>ComEventGrant</code>-Freigabe für das konkrete <code>ServiceEventDeployment</code> besitzt.\n</li></ul>\n</li><li><strong>Fehlerpfad &amp; Abbruchbedingung:</strong>\n<ul class=\"fig-list\"><li>Fehlt ein passender <code>ComEventGrant</code>, wird der Zugriff verweigert: <code>ara::com</code> schlägt mit einem entsprechenden Fehlercode (z. B. <code>kGrantEnforcementFailed</code> bzw. Zugriffsverweigerung) fehl, und es erfolgt ein Security-Event-Logging via DLT/IAM.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Zweistufiges Design- vs. Deployment-Pattern:</strong>\n<ul class=\"fig-list\"><li>Architekten definieren Berechtigungen zunächst abstrakt (<code>ComEventGrantDesign</code> via <code>ComGrantDesign</code> verknüpft mit <code>ProcessDesign</code>), während System-Integratoren die verbindlichen Laufzeit-Rechte über <code>ComEventGrant</code> (spezialisiert von <code>ComGrant</code>) konfigurieren.\n</li></ul>\n</li><li><strong>Optionale Kardinalitäten (<code>0..1</code>):</strong>\n<ul class=\"fig-list\"><li>Die Assoziationen <code>+serviceInstance</code> (an <code>ComGrant</code>) und <code>+serviceDeployment</code> (an <code>ComEventGrant</code>) besitzen nun die Kardinalität <code>0..1</code> statt zuvor strikt <code>1</code>. Dies gestattet flexiblere Konstellationen bei der schrittweisen Modellierung oder partiellen Autorisierung von Service- und Event-Deployments.\n</li></ul>\n</li><li><strong>Konfigurationsfalle (Silent Failure / Denial of Service):</strong>\n<ul class=\"fig-list\"><li>Ist in einer Adaptive-Umgebung das IAM aktiv, führt das Fehlen des passenden Grants im Manifest dazu, dass Event-Subscriptions trotz korrekt konfigurierter Netzwerkanbindung auf Middleware-Ebene blockiert werden.\n</li></ul>\n</li><li><strong>Port-Mapping-Konsistenz:</strong>\n<ul class=\"fig-list\"><li>Integratoren müssen sicherstellen, dass die über <code>ComGrant</code> autorisierte <code>AdaptivePlatformServiceInstance</code> konsistent über <code>ServiceInstanceToPortPrototypeMapping</code> dem <code>PortPrototype</code> des Prozesses zugeordnet ist.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-6116c5f5b5d4f9da", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-2.0-Metamodell-Klassendiagramm (M2-Ebene nach AUTOSAR-Metamodell-Architektur).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP), Teilspezifikation <em>Manifest Specification</em> (<code>AUTOSAR_TPS_ManifestSpecification</code>, Release R23-11).\n</li><li><strong>Funktionaler Zweck:</strong> Modellierung der Zugriffsberechtigungen für Kommunikations-Events im Rahmen des <em>Identity and Access Management</em> (IAM) und des <em>Communication Management</em> (<code>ara::com</code>). Es definiert die formalen Beziehungen zur Gewährung von Zugriffsrechten (<code>ComEventGrant</code> als Spezialisierung von <code>ComGrant</code>) auf Instanz- und Deployment-Ebene sowie deren Entsprechung im Software-Design (<code>ComEventGrantDesign</code> als Spezialisierung von <code>ComGrantDesign</code>) gemäß den Anforderungen <code>RS_MANI_00060</code> und <code>TPS_MANI_01240</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen &amp; Stereotypen</h5>\n<ul class=\"fig-list\"><li><strong><code>ComGrant</code></strong> (Spezialisierung von <code>Grant</code>):\n<ul class=\"fig-list\"><li>Abstrakte Zwischenklasse für Kommunikations-Grants.\n</li><li>Assoziationen:\n<ul class=\"fig-list\"><li><code>+serviceInstance</code>: Referenziert optional (<code>[0..1]</code>) eine <code>AdaptivePlatformServiceInstance</code>.\n</li><li><code>+remoteSubject</code>: Referenziert <code>0..*</code> entfernte IAM-Subjekte vom Typ <code>AbstractIamRemoteSubject</code>.\n</li></ul>\n</li></ul>\n</li><li><strong><code>ComEventGrant</code></strong> (Spezialisierung von <code>ComGrant</code>):\n<ul class=\"fig-list\"><li>Konkretes Deployment-Artefakt zur Freigabe des Zugriffs auf ein bestimmtes Event einer Service-Instanz.\n</li><li>Assoziationen:\n<ul class=\"fig-list\"><li><code>+serviceDeployment</code>: Referenziert optional (<code>[0..1]</code>) ein Event-Deployment <code>ServiceEventDeployment</code>.\n</li><li><code>+design</code> (<code>«atpUriDef»</code>): Optionale Referenz (<code>[0..1]</code>) auf das korrespondierende Entwurfsartefakt <code>ComEventGrantDesign</code>.\n</li></ul>\n</li></ul>\n</li><li><strong><code>AbstractIamRemoteSubject</code></strong> (<code>UploadableDeploymentElement</code>):\n<ul class=\"fig-list\"><li>Repräsentiert ein entferntes Kommunikationssubjekt für die IAM-Autorisierung als auslieferbares Deployment-Element.\n</li></ul>\n</li><li><strong><code>ComGrantDesign</code></strong> (Spezialisierung von <code>GrantDesign</code>):\n<ul class=\"fig-list\"><li>Abstrakte Basisklasse für Entwurfszeit-Kommunikations-Grants.\n</li></ul>\n</li><li><strong><code>ComEventGrantDesign</code></strong> (Spezialisierung von <code>ComGrantDesign</code>):\n<ul class=\"fig-list\"><li>Entwurfszeit-Pendant zur Spezifikation von Berechtigungen auf Software-Architekturebene unabhängig vom konkreten Deployment.\n</li></ul>\n</li><li><strong><code>GrantDesign</code></strong> (<code>ARElement</code>):\n<ul class=\"fig-list\"><li>Abstrakte Basisklasse für Design-Grants.\n</li><li>Assoziation: Referenziert über <code>+processDesign</code> optional (<code>[0..1]</code>) ein <code>ProcessDesign</code>.\n</li></ul>\n</li><li><strong><code>ProcessDesign</code></strong> (<code>ARElement</code>):\n<ul class=\"fig-list\"><li>Repräsentiert den Prozessentwurf auf Architekturebene.\n</li><li>Wird referenziert von:\n<ul class=\"fig-list\"><li><code>Process</code> über Rolle <code>+design [0..1]</code>.\n</li><li><code>ServiceInstanceToPortPrototypeMapping</code> über Rolle <code>+processDesign [0..1]</code> (<code>«atpUriDef»</code>).\n</li></ul>\n</li></ul>\n</li><li><strong><code>Process</code></strong> (Spezialisierung von <code>AbstractExecutionContext</code>):\n<ul class=\"fig-list\"><li>Repräsentiert die konkrete OS-Prozessinstanz zur Laufzeit.\n</li></ul>\n</li><li><strong><code>AdaptivePlatformServiceInstance</code></strong> (<code>UploadableDesignElement</code>):\n<ul class=\"fig-list\"><li>Repräsentiert eine Service-Instanz auf Design-Ebene.\n</li><li>Assoziation: Referenziert über <code>+serviceInterfaceDeployment</code> optional (<code>[0..1]</code>) ein <code>ServiceInterfaceDeployment</code>.\n</li></ul>\n</li><li><strong><code>ServiceInterfaceDeployment</code></strong> (<code>UploadableDesignElement</code>):\n<ul class=\"fig-list\"><li>Protokollspezifische Bindung eines Service-Interfaces auf Design-Ebene.\n</li><li>Komposition (schwarze Raute, <code>«atpVariation,atpSplitable»</code>): Aggregiert <code>0..*</code> <code>ServiceEventDeployment</code>-Elemente über die Rolle <code>+eventDeployment</code>.\n</li></ul>\n</li><li><strong><code>ServiceEventDeployment</code></strong> (<code>Identifiable</code>):\n<ul class=\"fig-list\"><li>Transport- und serialisierungsspezifisches Deployment eines einzelnen Events (z. B. SOME/IP Event ID, Event Groups).\n</li></ul>\n</li><li><strong><code>ServiceInstanceToPortPrototypeMapping</code></strong> (<code>UploadableDesignElement</code>):\n<ul class=\"fig-list\"><li>Verknüpft Ports mit Service-Instanzen und Prozessen auf Design-Ebene.\n</li><li>Assoziationen:\n<ul class=\"fig-list\"><li><code>+process</code> (<code>«atpSplitable»</code>): Referenziert optional (<code>[0..1]</code>) einen <code>Process</code>.\n</li><li><code>+processDesign</code> (<code>«atpUriDef»</code>): Referenziert optional (<code>[0..1]</code>) ein <code>ProcessDesign</code>.\n</li><li><code>+serviceInstance</code>: Referenziert optional (<code>[0..1]</code>) eine <code>AdaptivePlatformServiceInstance</code>.\n</li><li><code>+portPrototype</code> (<code>«instanceRef,atpUriDef»</code>): Instanzreferenz (<code>[0..1]</code>) auf einen <code>PortPrototype</code>.\n</li></ul>\n</li></ul>\n</li><li><strong><code>PortPrototype</code></strong> (<code>AtpBlueprintable</code>, <code>AtpPrototype</code>):\n<ul class=\"fig-list\"><li>Architektureller Kommunikationsendpunkt (RPort/PPort) einer Software-Komponente.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell für den Manifest-Entwurf handelt, existiert kein Sequenzdiagramm; das Diagramm determiniert jedoch zwingend folgende Laufzeitabläufe im AP IAM- und IPC-Stack:</p>\n<ol class=\"fig-list\"><li><strong>Deployment- &amp; Startphase (Execution Management):</strong>\n<ul class=\"fig-list\"><li>Beim Parsen des <em>Execution Manifests</em> und des <em>Service Instance Manifests</em> erzeugt die IAM-Instanz Zugriffskontrolltabellen (ACLs / Capabilities) für den jeweiligen <code>Process</code>.\n</li></ul>\n</li><li><strong>Access Control Check (<code>ara::com</code> Subscription/FindService):</strong>\n<ul class=\"fig-list\"><li>Ruft eine Applikation innerhalb eines Prozesses Methoden wie <code>FindService()</code>, <code>Subscribe()</code> oder <code>Send()</code> für ein Event auf, fängt der Middleware-Stack (<code>ara::com</code>) bzw. der IAM-Policy-Enforcement-Point (PEP) die Anfrage ab.\n</li></ul>\n</li><li><strong>Validierungspfad:</strong>\n<ul class=\"fig-list\"><li>Der PEP prüft, ob die Prozess-ID/UID über das Mapping (<code>ServiceInstanceToPortPrototypeMapping</code> → <code>AdaptivePlatformServiceInstance</code>) eine explizite <code>ComEventGrant</code>-Freigabe für das konkrete <code>ServiceEventDeployment</code> besitzt.\n</li></ul>\n</li><li><strong>Fehlerpfad &amp; Abbruchbedingung:</strong>\n<ul class=\"fig-list\"><li>Fehlt ein passender <code>ComEventGrant</code>, wird der Zugriff verweigert: <code>ara::com</code> schlägt mit einem entsprechenden Fehlercode (z. B. <code>kGrantEnforcementFailed</code> bzw. Zugriffsverweigerung) fehl, und es erfolgt ein Security-Event-Logging via DLT/IAM.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Zweistufiges Design- vs. Deployment-Pattern:</strong>\n<ul class=\"fig-list\"><li>Architekten definieren Berechtigungen zunächst abstrakt (<code>ComEventGrantDesign</code> via <code>ComGrantDesign</code> verknüpft mit <code>ProcessDesign</code>), während System-Integratoren die verbindlichen Laufzeit-Rechte über <code>ComEventGrant</code> (spezialisiert von <code>ComGrant</code>) konfigurieren.\n</li></ul>\n</li><li><strong>Optionale Kardinalitäten (<code>0..1</code>):</strong>\n<ul class=\"fig-list\"><li>Die Assoziationen <code>+serviceInstance</code> (an <code>ComGrant</code>) und <code>+serviceDeployment</code> (an <code>ComEventGrant</code>) besitzen nun die Kardinalität <code>0..1</code> statt zuvor strikt <code>1</code>. Dies gestattet flexiblere Konstellationen bei der schrittweisen Modellierung oder partiellen Autorisierung von Service- und Event-Deployments.\n</li></ul>\n</li><li><strong>Konfigurationsfalle (Silent Failure / Denial of Service):</strong>\n<ul class=\"fig-list\"><li>Ist in einer Adaptive-Umgebung das IAM aktiv, führt das Fehlen des passenden Grants im Manifest dazu, dass Event-Subscriptions trotz korrekt konfigurierter Netzwerkanbindung auf Middleware-Ebene blockiert werden.\n</li></ul>\n</li><li><strong>Port-Mapping-Konsistenz:</strong>\n<ul class=\"fig-list\"><li>Integratoren müssen sicherstellen, dass die über <code>ComGrant</code> autorisierte <code>AdaptivePlatformServiceInstance</code> konsistent über <code>ServiceInstanceToPortPrototypeMapping</code> dem <code>PortPrototype</code> des Prozesses zugeordnet ist.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-c83ac6449de8b98a", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-2.0-Metamodell-Klassendiagramm (M2-Ebene nach AUTOSAR-Metamodell-Architektur).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP), Teilspezifikation <em>Manifest Specification</em> (<code>AUTOSAR_TPS_ManifestSpecification</code>, Release R25-11).\n</li><li><strong>Funktionaler Zweck:</strong> Modellierung der Zugriffsberechtigungen für Kommunikations-Events im Rahmen des <em>Identity and Access Management</em> (IAM) und des <em>Communication Management</em> (<code>ara::com</code>). Es definiert die formalen Beziehungen zur Gewährung von Zugriffsrechten (<code>ComEventGrant</code> als Spezialisierung von <code>ComGrant</code>) auf Instanz- und Deployment-Ebene sowie deren Entsprechung im Software-Design (<code>ComEventGrantDesign</code> als Spezialisierung von <code>ComGrantDesign</code>) gemäß den Anforderungen <code>RS_MANI_00060</code> und <code>TPS_MANI_01240</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen &amp; Stereotypen</h5>\n<ul class=\"fig-list\"><li><strong><code>ComGrant</code></strong> (Spezialisierung von <code>Grant</code>):\n<ul class=\"fig-list\"><li>Abstrakte Zwischenklasse für Kommunikations-Grants.\n</li><li>Assoziationen:\n<ul class=\"fig-list\"><li><code>+serviceInstance</code>: Referenziert optional (<code>[0..1]</code>) eine <code>AdaptivePlatformServiceInstance</code>.\n</li><li><code>+remoteSubject</code>: Referenziert <code>0..*</code> entfernte IAM-Subjekte vom Typ <code>AbstractIamRemoteSubject</code>.\n</li></ul>\n</li></ul>\n</li><li><strong><code>ComEventGrant</code></strong> (Spezialisierung von <code>ComGrant</code>):\n<ul class=\"fig-list\"><li>Konkretes Deployment-Artefakt zur Freigabe des Zugriffs auf ein bestimmtes Event einer Service-Instanz.\n</li><li>Assoziationen:\n<ul class=\"fig-list\"><li><code>+serviceDeployment</code>: Referenziert optional (<code>[0..1]</code>) ein Event-Deployment <code>ServiceEventDeployment</code>.\n</li><li><code>+design</code> (<code>«atpUriDef»</code>): Optionale Referenz (<code>[0..1]</code>) auf das korrespondierende Entwurfsartefakt <code>ComEventGrantDesign</code>.\n</li></ul>\n</li></ul>\n</li><li><strong><code>AbstractIamRemoteSubject</code></strong> (<code>UploadableDeploymentElement</code>):\n<ul class=\"fig-list\"><li>Repräsentiert ein entferntes Kommunikationssubjekt für die IAM-Autorisierung als auslieferbares Deployment-Element.\n</li></ul>\n</li><li><strong><code>ComGrantDesign</code></strong> (Spezialisierung von <code>GrantDesign</code>):\n<ul class=\"fig-list\"><li>Abstrakte Basisklasse für Entwurfszeit-Kommunikations-Grants.\n</li></ul>\n</li><li><strong><code>ComEventGrantDesign</code></strong> (Spezialisierung von <code>ComGrantDesign</code>):\n<ul class=\"fig-list\"><li>Entwurfszeit-Pendant zur Spezifikation von Berechtigungen auf Software-Architekturebene unabhängig vom konkreten Deployment.\n</li></ul>\n</li><li><strong><code>GrantDesign</code></strong> (<code>ARElement</code>):\n<ul class=\"fig-list\"><li>Abstrakte Basisklasse für Design-Grants.\n</li><li>Assoziation: Referenziert über <code>+processDesign</code> optional (<code>[0..1]</code>) ein <code>ProcessDesign</code>.\n</li></ul>\n</li><li><strong><code>ProcessDesign</code></strong> (<code>ARElement</code>):\n<ul class=\"fig-list\"><li>Repräsentiert den Prozessentwurf auf Architekturebene.\n</li><li>Wird referenziert von:\n<ul class=\"fig-list\"><li><code>Process</code> über Rolle <code>+design [0..1]</code>.\n</li><li><code>ServiceInstanceToPortPrototypeMapping</code> über Rolle <code>+processDesign [0..1]</code> (<code>«atpUriDef»</code>).\n</li></ul>\n</li></ul>\n</li><li><strong><code>Process</code></strong> (Spezialisierung von <code>AbstractExecutionContext</code>):\n<ul class=\"fig-list\"><li>Repräsentiert die konkrete OS-Prozessinstanz zur Laufzeit.\n</li></ul>\n</li><li><strong><code>AdaptivePlatformServiceInstance</code></strong> (<code>UploadableDesignElement</code>):\n<ul class=\"fig-list\"><li>Repräsentiert eine Service-Instanz auf Design-Ebene.\n</li><li>Assoziation: Referenziert über <code>+serviceInterfaceDeployment</code> optional (<code>[0..1]</code>) ein <code>ServiceInterfaceDeployment</code>.\n</li></ul>\n</li><li><strong><code>ServiceInterfaceDeployment</code></strong> (<code>UploadableDesignElement</code>):\n<ul class=\"fig-list\"><li>Protokollspezifische Bindung eines Service-Interfaces auf Design-Ebene.\n</li><li>Komposition (schwarze Raute, <code>«atpVariation,atpSplitable»</code>): Aggregiert <code>0..*</code> <code>ServiceEventDeployment</code>-Elemente über die Rolle <code>+eventDeployment</code>.\n</li></ul>\n</li><li><strong><code>ServiceEventDeployment</code></strong> (<code>ServiceInterfaceDeploymentElement</code>):\n<ul class=\"fig-list\"><li>Transport- und serialisierungsspezifisches Deployment eines einzelnen Events (z. B. SOME/IP Event ID, Event Groups), nun abgeleitet von <code>ServiceInterfaceDeploymentElement</code>.\n</li></ul>\n</li><li><strong><code>ServiceInstanceToPortPrototypeMapping</code></strong> (<code>UploadableDesignElement</code>):\n<ul class=\"fig-list\"><li>Verknüpft Ports mit Service-Instanzen und Prozessen auf Design-Ebene.\n</li><li>Assoziationen:\n<ul class=\"fig-list\"><li><code>+process</code> (<code>«atpSplitable»</code>): Referenziert optional (<code>[0..1]</code>) einen <code>Process</code>.\n</li><li><code>+processDesign</code> (<code>«atpUriDef»</code>): Referenziert optional (<code>[0..1]</code>) ein <code>ProcessDesign</code>.\n</li><li><code>+serviceInstance</code>: Referenziert optional (<code>[0..1]</code>) eine <code>AdaptivePlatformServiceInstance</code>.\n</li><li><code>+portPrototype</code> (<code>«instanceRef,atpUriDef»</code>): Instanzreferenz (<code>[0..1]</code>) auf einen <code>PortPrototype</code>.\n</li></ul>\n</li></ul>\n</li><li><strong><code>PortPrototype</code></strong> (<code>AtpBlueprintable</code>, <code>AtpPrototype</code>):\n<ul class=\"fig-list\"><li>Architektureller Kommunikationsendpunkt (RPort/PPort) einer Software-Komponente.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell für den Manifest-Entwurf handelt, existiert kein Sequenzdiagramm; das Diagramm determiniert jedoch zwingend folgende Laufzeitabläufe im AP IAM- und IPC-Stack:</p>\n<ol class=\"fig-list\"><li><strong>Deployment- &amp; Startphase (Execution Management):</strong>\n<ul class=\"fig-list\"><li>Beim Parsen des <em>Execution Manifests</em> und des <em>Service Instance Manifests</em> erzeugt die IAM-Instanz Zugriffskontrolltabellen (ACLs / Capabilities) für den jeweiligen <code>Process</code>.\n</li></ul>\n</li><li><strong>Access Control Check (<code>ara::com</code> Subscription/FindService):</strong>\n<ul class=\"fig-list\"><li>Ruft eine Applikation innerhalb eines Prozesses Methoden wie <code>FindService()</code>, <code>Subscribe()</code> oder <code>Send()</code> für ein Event auf, fängt der Middleware-Stack (<code>ara::com</code>) bzw. der IAM-Policy-Enforcement-Point (PEP) die Anfrage ab.\n</li></ul>\n</li><li><strong>Validierungspfad:</strong>\n<ul class=\"fig-list\"><li>Der PEP prüft, ob die Prozess-ID/UID über das Mapping (<code>ServiceInstanceToPortPrototypeMapping</code> → <code>AdaptivePlatformServiceInstance</code>) eine explizite <code>ComEventGrant</code>-Freigabe für das konkrete <code>ServiceEventDeployment</code> besitzt.\n</li></ul>\n</li><li><strong>Fehlerpfad &amp; Abbruchbedingung:</strong>\n<ul class=\"fig-list\"><li>Fehlt ein passender <code>ComEventGrant</code>, wird der Zugriff verweigert: <code>ara::com</code> schlägt mit einem entsprechenden Fehlercode (z. B. <code>kGrantEnforcementFailed</code> bzw. Zugriffsverweigerung) fehl, und es erfolgt ein Security-Event-Logging via DLT/IAM.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Zweistufiges Design- vs. Deployment-Pattern:</strong>\n<ul class=\"fig-list\"><li>Architekten definieren Berechtigungen zunächst abstrakt (<code>ComEventGrantDesign</code> via <code>ComGrantDesign</code> verknüpft mit <code>ProcessDesign</code>), während System-Integratoren die verbindlichen Laufzeit-Rechte über <code>ComEventGrant</code> (spezialisiert von <code>ComGrant</code>) konfigurieren.\n</li></ul>\n</li><li><strong>Optionale Kardinalitäten (<code>0..1</code>):</strong>\n<ul class=\"fig-list\"><li>Die Assoziationen <code>+serviceInstance</code> (an <code>ComGrant</code>) und <code>+serviceDeployment</code> (an <code>ComEventGrant</code>) besitzen nun die Kardinalität <code>0..1</code> statt zuvor strikt <code>1</code>. Dies gestattet flexiblere Konstellationen bei der schrittweisen Modellierung oder partiellen Autorisierung von Service- und Event-Deployments.\n</li></ul>\n</li><li><strong>Konfigurationsfalle (Silent Failure / Denial of Service):</strong>\n<ul class=\"fig-list\"><li>Ist in einer Adaptive-Umgebung das IAM aktiv, führt das Fehlen des passenden Grants im Manifest dazu, dass Event-Subscriptions trotz korrekt konfigurierter Netzwerkanbindung auf Middleware-Ebene blockiert werden.\n</li></ul>\n</li><li><strong>Port-Mapping-Konsistenz:</strong>\n<ul class=\"fig-list\"><li>Integratoren müssen sicherstellen, dass die über <code>ComGrant</code> autorisierte <code>AdaptivePlatformServiceInstance</code> konsistent über <code>ServiceInstanceToPortPrototypeMapping</code> dem <code>PortPrototype</code> des Prozesses zugeordnet ist.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-c1cf32a17b39147e", "to": "FIG-5f75bd1c8fb50021", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Metaklasse <code>ComGrant</code> eingeführt: spezialisiert <code>Grant</code> und übernimmt die Assoziation <code>+serviceInstance</code> (<code>[1]</code>) zu <code>AdaptivePlatformServiceInstance</code>.\n</li><li>Metaklasse <code>ComEventGrant</code> spezialisiert nun <code>ComGrant</code> statt direkt <code>Grant</code>.\n</li><li>Metaklasse <code>AbstractIamRemoteSubject</code> (<code>ARElement</code>) eingeführt und über Assoziation <code>+remoteSubject</code> (<code>[0..*]</code>) an <code>ComGrant</code> angebunden.\n</li><li>Metaklasse <code>ComGrantDesign</code> als Basisklasse für <code>ComEventGrantDesign</code> eingeführt.\n</li><li>Metaklasse <code>Process</code>: Attribute <code>logTraceDefaultLogLevel</code>, <code>logTraceFilePath</code>, <code>logTraceLogMode</code>, <code>logTraceProcessDesc</code> und <code>logTraceProcessId</code> entfernt; Attribut <code>functionClusterAffiliation: String [0..1]</code> hinzugefügt.\n</li><li>Metaklasse <code>ServiceInstanceToPortPrototypeMapping</code>: Attribut <code>logTracePortId</code> entfernt; Assoziation <code>+process</code> (<code>[0..1]</code>, <code>«atpSplitable»</code>) zu <code>Process</code> ergänzt; Assoziationsrolle zu <code>ProcessDesign</code> als <code>+processDesign</code> (<code>[0..1]</code>, <code>«atpUriDef»</code>) präzisiert.\n</li></ul>"}, {"from": "FIG-5f75bd1c8fb50021", "to": "FIG-b061eeea61480361", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Metaklasse <code>ServiceInstanceToPortPrototypeMapping</code>: Attribut <code>enablesLogTrace: Boolean [0..1]</code> entfernt (Klasse besitzt nun keine Attribute mehr).\n</li></ul>"}, {"from": "FIG-b061eeea61480361", "to": "FIG-9baeaafcf15f8dd8", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Metaklasse <code>Process</code>: Sämtliche verbleibenden Attribute (<code>functionClusterAffiliation</code>, <code>numberOfRestartAttempts</code>, <code>preMapping</code>) aus der Diagrammdarstellung entfernt.\n</li><li>Assoziation <code>+serviceDeployment</code> von <code>ComEventGrant</code> zu <code>ServiceEventDeployment</code>: Kardinalität von <code>1</code> auf <code>0..1</code> geändert.\n</li><li>Assoziation <code>+serviceInstance</code> von <code>ComGrant</code> zu <code>AdaptivePlatformServiceInstance</code>: Kardinalität von <code>1</code> auf <code>0..1</code> geändert.\n</li><li>Diagrammlayout: <code>ComEventGrant</code> von einem die gesamte Breite einnehmenden Kasten in einen kompakten Kasten unten rechts umstrukturiert.\n</li></ul>"}, {"from": "FIG-9baeaafcf15f8dd8", "to": "FIG-2cbd2bea127981b1", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Metaklassen <code>AdaptivePlatformServiceInstance</code>, <code>ServiceInterfaceDeployment</code> und <code>ServiceInstanceToPortPrototypeMapping</code>: Paketierungsklassifikation von <code>UploadablePackageElement</code> zu <code>UploadableDesignElement</code> geändert.\n</li><li>Metaklasse <code>AbstractIamRemoteSubject</code>: Klassifikation von <code>ARElement</code> zu <code>UploadableDeploymentElement</code> geändert.\n</li><li>Kompositionsassoziation <code>+eventDeployment</code> (<code>[0..*]</code>) von <code>ServiceInterfaceDeployment</code> zu <code>ServiceEventDeployment</code>: Stereotyp <code>«atpVariation,atpSplitable»</code> hinzugefügt.\n</li></ul>"}, {"from": "FIG-2cbd2bea127981b1", "to": "FIG-6116c5f5b5d4f9da", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-6116c5f5b5d4f9da", "to": "FIG-c83ac6449de8b98a", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Metaklasse <code>ServiceEventDeployment</code>: Basisklasse von <code>Identifiable</code> zu <code>ServiceInterfaceDeploymentElement</code> geändert.\n</li></ul>"}]};
